package mrpapermoon.whisper.navigation@Suppress("ClassName")sealed interface NavigationScreen {	data object splash : NavigationScreen	sealed interface main : NavigationScreen {		data object write : main		data object by_whisperer : main		companion object : main {			override fun toString(): String = "main"		}	}	data object profile : NavigationScreen	data object settings : NavigationScreen	companion object {		val DEFAULT: NavigationScreen			get() = splash	}}